// Writes meta.generated.ts from the full Lesson, Challenge, exam and Explainer
// definitions. Run after changing a title, summary, track or the Steps:
//
//   bun lib/lessons/gen-meta.ts
//
// meta.test.ts fails while the generated file is out of date.

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { EXPLAINERS } from "@/lib/explainers/explainers";
import { CHALLENGES } from "./challenges";
import { EXAMS } from "./exams";
import { LESSONS, type Lesson } from "./lessons";

const lesson = (l: Lesson) => ({
  slug: l.slug,
  title: l.title,
  ...(l.short ? { short: l.short } : {}),
  summary: l.summary,
  minutes: l.minutes,
  concepts: l.concepts,
  ...(l.track ? { track: l.track } : {}),
  steps: l.steps.map((s) => ({ title: s.title })),
});

/** The generated data, as plain JSON-able values. */
export function metaData() {
  return {
    LESSONS: LESSONS.map(lesson),
    CHALLENGES: CHALLENGES.map((c) => ({ ...lesson(c), difficulty: c.difficulty, brief: c.brief })),
    EXAMS: EXAMS.map((e) => ({ slug: e.slug, title: e.title, style: e.style, summary: e.summary, minutes: e.minutes, passPercent: e.passPercent, tasks: e.tasks.map((t) => ({ title: t.title, points: t.points, ...(t.namespace ? { namespace: t.namespace } : {}) })) })),
    EXPLAINER_DATA: EXPLAINERS.map((e) => ({ id: e.id, title: e.title, summary: e.summary, concept: e.concept, ...(e.param ? { param: e.param } : {}), beatTitles: e.beats(e.param?.default ?? 0).map((b) => b.title) })),
  };
}

const TYPES: Record<keyof ReturnType<typeof metaData>, string> = {
  LESSONS: "LessonMeta[]",
  CHALLENGES: "ChallengeMeta[]",
  EXAMS: "ExamMeta[]",
  EXPLAINER_DATA: '(Omit<ExplainerMeta, "beats"> & { beatTitles: string[] })[]',
};

export function renderMeta(): string {
  const data = metaData();
  const body = (Object.keys(TYPES) as (keyof typeof TYPES)[]).map((k) => `export const ${k}: ${TYPES[k]} = ${JSON.stringify(data[k], null, 2)};\n`).join("\n");
  return `// GENERATED by \`bun lib/lessons/gen-meta.ts\` from lessons.ts, challenges.ts, exams.ts and
// explainers.ts. Do not edit by hand; meta.test.ts fails when this is stale.

import type { ChallengeMeta, ExamMeta, ExplainerMeta, LessonMeta } from "./meta";

${body}`;
}

export const META_FILE = join(import.meta.dir, "meta.generated.ts");

if (import.meta.main) {
  writeFileSync(META_FILE, renderMeta());
  console.log(`wrote ${META_FILE}`);
}
